<template>
  <AppLayout>
    <main class="mx-auto w-full max-w-7xl flex-1 px-4 py-10 sm:px-6 lg:px-8">
      <p class="text-sm font-semibold text-[#008060]">Карьерный навигатор</p>
      <h1 class="mt-2 text-3xl font-semibold tracking-tight text-[#202223]">Поймите, где вы сейчас и куда расти дальше</h1>
      <p class="mt-3 max-w-3xl text-[#616161]">Сначала оценим рабочий уровень, затем учтём навыки и выбранное направление. Это займёт несколько минут.</p>

      <div v-if="readonlyReport" class="mt-8"><section class="report"><ReportContent :result="result" :error="error" :copied="copied" @copy="copyLink" /></section></div>

      <div v-else class="mt-8 grid gap-6 lg:grid-cols-[minmax(0,1fr)_360px]">
        <form class="rounded-xl border border-[#e1e3e5] bg-white p-6 shadow-sm" @submit.prevent="submit">
          <div class="steps" aria-label="Этапы создания карьерного плана"><span :class="{ active: step >= 1 }">1. Уровень</span><span :class="{ active: step >= 2 }">2. Навыки</span><span :class="{ active: step >= 3 }">3. Цель</span></div>
          <section v-if="step === 1" class="space-y-6">
            <div><h2>Определим текущий уровень</h2><p>Отвечайте по реальному опыту работы, а не по названию должности.</p></div>
            <div class="question"><b>1. Есть ли у вас коммерческий опыт в IT?</b><div class="mt-3 options"><label v-for="item in experienceOptions" :key="item.value" class="option"><input v-model="form.commercial_experience" type="radio" :value="item.value"/><span>{{ item.label }}</span></label></div></div>
            <div class="question"><b>2. Есть ли пример задачи или проекта, который вы довели от постановки до результата?</b><div class="mt-3 options"><label class="option"><input v-model="form.completed_project" type="radio" :value="true"/><span>Да, могу описать задачу, своё решение и результат.</span></label><label class="option"><input v-model="form.completed_project" type="radio" :value="false"/><span>Пока нет такого примера.</span></label></div></div>
            <div v-for="(question, index) in gradeQuestions" :key="question.title" class="question"><b>{{ index + 3 }}. {{ question.title }}</b><div class="mt-3 space-y-2"><label v-for="option in question.options" :key="option.value" class="option"><input v-model="form.grade_answers[index]" type="radio" :value="option.value"/><span>{{ option.text }}</span></label></div></div>
          </section>
          <section v-else-if="step === 2" class="space-y-6"><div><h2>Расскажите о навыках</h2><p>Сначала выберите направление, затем отметьте инструменты, с которыми уже работали на практике.</p></div><div><label class="label" for="career-direction">Направление</label><select id="career-direction" v-model="form.group_id" class="field"><option :value="null">Помочь определить</option><option v-for="group in groups" :key="group.id" :value="group.id">{{ group.title }}</option></select><p class="mt-2 text-xs text-[#6d7175]">Направление уточняет стартовый список навыков. Его можно не выбирать.</p></div><div><div class="mb-2 flex justify-between"><label class="label" for="skill-search">Ваши навыки</label><button v-if="form.skills.length" type="button" class="text-xs font-semibold text-[#008060]" @click="form.skills = []">Очистить</button></div><div class="skill-picker"><input id="skill-search" v-model="skillQuery" type="search" class="field" placeholder="Поиск или выбор навыка" @focus="isSkillMenuOpen = true"/><button type="button" class="skill-menu-toggle" :aria-expanded="isSkillMenuOpen" aria-label="Открыть список навыков" @click="isSkillMenuOpen = !isSkillMenuOpen"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M4 5h8M4 10h8M4 15h8M15 4.5l1.5 1.5L15 7.5M15 10.5l1.5 1.5-1.5 1.5" /></svg></button></div><div v-if="isSkillMenuOpen" class="skill-results"><p class="skill-results-title">{{ skillMenuTitle }}</p><label v-for="skill in visibleSkillOptions" :key="skill.id" class="skill-option"><input type="checkbox" :checked="selected(skill.id)" @change="toggleSkill(skill.id)"/><span>{{ skill.title }}</span><small v-if="selected(skill.id)">Выбрано</small></label><p v-if="!visibleSkillOptions.length" class="skill-results-empty">Ничего не найдено. Попробуйте другое название.</p></div><p class="mt-2 text-xs text-[#6d7175]">Можно выбрать несколько навыков. Не отмечайте инструменты, которые пока не применяли.</p><div v-if="selectedSkills.length" class="mt-3 flex flex-wrap gap-2"><button v-for="skill in selectedSkills" :key="skill.id" type="button" class="tag" @click="toggleSkill(skill.id)">{{ skill.title }} <span aria-hidden="true">×</span></button></div></div></section>
          <section v-else class="space-y-6"><div><h2>Выберите цель</h2><p>Цель не меняет ваш текущий уровень - она помогает составить подходящий маршрут развития.</p></div><div><label class="label">Интересующая роль</label><select v-model="form.category_id" class="field"><option :value="null">Предложить подходящую роль</option><option v-for="category in availableCategories" :key="category.id" :value="category.id">{{ category.title }}</option></select></div><div class="summary"><span>Предварительный уровень</span><b>{{ preliminaryLevel }}</b><small>{{ preliminaryText }}</small></div></section>
          <p v-if="formError" class="form-error">{{ formError }}</p><div class="mt-8 flex items-center justify-between gap-3"><button v-if="step > 1" type="button" class="back" @click="step--">Назад</button><span v-else></span><button v-if="step < 3" type="button" class="primary" @click="nextStep">Продолжить</button><button v-else :disabled="loading" class="primary">{{ loading ? 'Формируем…' : 'Построить карьерный план' }}</button></div>
        </form>
        <aside class="rounded-xl border border-[#e1e3e5] bg-[#f7f8f8] p-6"><p class="text-sm font-semibold text-[#008060]">Что вы получите</p><h2 class="mt-2 text-xl font-semibold">Персональный ориентир развития</h2><ul class="mt-5 space-y-4 text-sm text-[#616161]"><li><b>Текущий уровень</b><br/>по опыту и самостоятельности, а не только по навыкам.</li><li><b>Следующий шаг</b><br/>достижимая роль в выбранном направлении.</li><li><b>План развития</b><br/>навыки, которые помогут подготовиться к переходу.</li></ul></aside>
      </div>
      <section v-if="!readonlyReport && result" class="mt-8"><ReportContent :result="result" :error="error" :copied="copied" @copy="copyLink" /></section>
    </main>
  </AppLayout>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue';
import AppLayout from '@/Layouts/AppLayout.vue';
import ReportContent from '@/Components/RecommendationReport.vue';
const props = defineProps({ skills: Array, groups: Array, categories: Array, qualifications: Array, popularSkillIds: Array, popularSkillIdsByGroup: Object, reportUuid: String });
const step = ref(1), skillQuery = ref(''), isSkillMenuOpen = ref(false), result = ref(null), error = ref(''), formError = ref(''), loading = ref(false), copied = ref(false), uuid = ref(props.reportUuid || null);
const form = ref({ commercial_experience: null, completed_project: null, grade_answers: [null, null, null, null, null], skills: [], group_id: null, category_id: null });
const readonlyReport = computed(() => Boolean(props.reportUuid || result.value?.report_uuid));
const experienceOptions = [{ value: 'none', label: 'Нет, ищу первую работу или стажировку' }, { value: 'up_to_year', label: 'Да, до 1 года' }, { value: 'one_to_three', label: 'Да, от 1 до 3 лет' }, { value: 'three_plus', label: 'Да, более 3 лет' }];
const gradeQuestions = [
  { title: 'Как вы обычно работаете над задачей?', options: [{ value: 0, text: 'Нужна подробная инструкция и регулярная проверка.' }, { value: 1, text: 'Сам выполняю типовые задачи, сложное согласовываю.' }, { value: 2, text: 'Сам выбираю подход и отвечаю за результат.' }, { value: 3, text: 'Определяю подход для команды и помогаю другим.' }] },
  { title: 'За что вы отвечаете?', options: [{ value: 0, text: 'За небольшой участок работы.' }, { value: 1, text: 'За задачу целиком.' }, { value: 2, text: 'За качество решений в части продукта.' }, { value: 3, text: 'За направление или результат команды.' }] },
  { title: 'Как вы принимаете решения?', options: [{ value: 0, text: 'Работаю по инструкции или готовому примеру.' }, { value: 1, text: 'Ищу решение сам, при необходимости спрашиваю.' }, { value: 2, text: 'Оцениваю варианты, риски и предлагаю решение.' }, { value: 3, text: 'Принимаю решения, влияющие на команду и продукт.' }] },
  { title: 'Как вы взаимодействуете с коллегами?', options: [{ value: 0, text: 'В основном получаю обратную связь от наставника.' }, { value: 1, text: 'Обсуждаю задачи с командой на равных.' }, { value: 2, text: 'Помогаю коллегам и объясняю сложные решения.' }, { value: 3, text: 'Развиваю людей, распределяю работу или нанимаю.' }] },
  { title: 'Как вы влияете на работу команды?', options: [{ value: 0, text: 'Пока осваиваю процессы и инструменты.' }, { value: 1, text: 'Предлагаю улучшения в своих задачах.' }, { value: 2, text: 'Улучшаю подходы и договорённости команды.' }, { value: 3, text: 'Планирую приоритеты и отвечаю за общий результат.' }] },
];
const availableCategories = computed(() => form.value.group_id ? props.categories.filter(item => item.group_id === form.value.group_id) : props.categories);
const selectedSkills = computed(() => props.skills.filter(item => form.value.skills.includes(item.id)));
const matchingSkills = computed(() => props.skills.filter(item => item.title.toLowerCase().includes(skillQuery.value.toLowerCase())).slice(0, 8));
const suggestedSkillIds = computed(() => form.value.group_id ? props.popularSkillIdsByGroup?.[form.value.group_id] || props.popularSkillIds || [] : props.popularSkillIds || []);
const suggestedSkills = computed(() => suggestedSkillIds.value.map(id => props.skills.find(skill => skill.id === id)).filter(Boolean));
const visibleSkillOptions = computed(() => skillQuery.value.trim() ? matchingSkills.value : suggestedSkills.value);
const skillMenuTitle = computed(() => skillQuery.value.trim() ? 'Результаты поиска' : form.value.group_id ? 'Популярные навыки выбранного направления' : 'Популярные навыки на рынке');
const selected = id => form.value.skills.includes(id);
const toggleSkill = id => { form.value.skills = selected(id) ? form.value.skills.filter(item => item !== id) : [...form.value.skills, id]; };
const preliminaryLevel = computed(() => { if (form.value.commercial_experience === 'none') return 'Intern'; const values = form.value.grade_answers.filter(item => item !== null); const avg = values.length ? values.reduce((sum, item) => sum + item, 0) / values.length : 0; const level = avg < .8 ? 'Junior' : avg < 1.8 ? 'Middle' : avg < 2.7 ? 'Senior' : 'Lead'; return level === 'Lead' && (form.value.commercial_experience === 'up_to_year' || form.value.completed_project === false) ? 'Senior' : level; });
const preliminaryText = computed(() => form.value.commercial_experience === 'none' ? 'Для первой роли важнее база, практика и завершённые проекты.' : 'Итог определён по вашим ответам о самостоятельности и ответственности.');
const nextStep = () => { formError.value = ''; if (step.value === 1 && (!form.value.commercial_experience || form.value.completed_project === null || form.value.grade_answers.some(item => item === null))) { formError.value = 'Ответьте на вопросы об опыте и выберите вариант для каждого утверждения.'; return; } if (step.value === 2 && !form.value.skills.length) { formError.value = 'Добавьте хотя бы один навык - так рекомендации будут полезнее.'; return; } step.value++; };
const request = async (url, options = {}) => { const response = await fetch(url, { headers: { 'Content-Type': 'application/json', Accept: 'application/json' }, ...options }); const data = await response.json(); if (!response.ok) throw new Error(data.message || 'Не удалось сформировать план'); return data; };
const submit = async () => { loading.value = true; error.value = ''; try { const data = await request('/api/recommendations', { method: 'POST', body: JSON.stringify(form.value) }); result.value = data.data; uuid.value = data.data.report_uuid; history.replaceState({}, '', `/recommendations/${uuid.value}`); } catch (exception) { error.value = exception.message; } finally { loading.value = false; } };
const copyLink = async () => { await navigator.clipboard.writeText(result.value.report_url); copied.value = true; setTimeout(() => copied.value = false, 1500); };
onMounted(async () => { if (!uuid.value) return; try { const data = await request(`/api/recommendations/${uuid.value}`); result.value = data.data; } catch (exception) { error.value = exception.message; } });
</script>

<style scoped>
