-radius:999px;background:#e3f1df;padding:.35rem .65rem;color:#006e52;font-size:.8rem}.summary{border:1px solid #b7d9c8;border-radius:.5rem;background:#f1f8f5;padding:1rem}.summary span,.summary small{display:block;color:#4a4f54;font-size:.8rem}.summary b{display:block;margin:.25rem 0;color:#006e52;font-size:1.2rem}.primary{border-radius:.375rem;background:#008060;padding:.7rem 1rem;color:#fff;font-size:.875rem;font-weight:600}.primary:disabled{opacity:.6}.back{border:1px solid #8c9196;border-radius:.375rem;padding:.65rem .9rem;font-size:.875rem}.form-error{margin-top:1.25rem;border:1px solid #f1b9b5;border-radius:.5rem;background:#fff5f4;padding:.75rem;color:#b42318;font-size:.875rem}.report{max-width:100%}.notice{border:1px solid #f1d59a;border-radius:.5rem;background:#fff8db;padding:1rem;font-size:.875rem;color:#6d5600}.copy{border:1px solid #b18a24;border-radius:.375rem;background:#fff;padding:.4rem .7rem;font-size:.75rem;font-weight:600;white-space:nowrap}.card,.panel{border:1px solid #e1e3e5;border-radius:.75rem;background:#fff;padding:1.25rem;box-shadow:0 1px 2px #0000000d}.card p,.card small,.inner p,.panel li p{color:#6d7175;font-size:.8rem}.card b{display:block;margin:.4rem 0;font-size:1.35rem}.panel{margin-top:1.25rem}.panel h2{font-size:1.1rem;font-weight:600}.inner{border:1px solid #e1e3e5;border-radius:.5rem;padding:1rem}.inner strong{display:block;margin-top:.75rem;color:#008060;font-size:.8rem}
</style>
